// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        bytes32 role = c.TIMELOCK_ADMIN_ROLE();
        // the deployer (this contract) holds TIMELOCK_ADMIN_ROLE, so it can grant to anyone
        vm.prank(address(this));
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor), "granted role must be reported by hasRole");
    }
}
